const normalize=v=>String(v||'').trim().toLocaleLowerCase().replace(/\s+/g,' ');
function findSubject(id){return subjects.find(s=>s.id===id)||subjects[0];}
function findTool(id){return tools.find(t=>t.id===id)||null;}
function detectSubject(label){
 const value=normalize(label); if(!value)return subjects[0];
 let best=subjects[0],score=0;
 subjects.forEach(s=>s.aliases.forEach(alias=>{
   const a=normalize(alias); let n=0;
   if(value===a)n=1000+a.length; else if(value.includes(a))n=500+a.length; else if(a.includes(value))n=100+value.length;
   if(n>score){best=s;score=n;}
 }));
 return best;
}
